import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"南吕·金字经偕叶云中山行","description":"","frontmatter":{"title":"南吕·金字经偕叶云中山行","date":"2026-11-18T00:00:00.000Z","seq":44,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"poem_quote":false,"author":"张可久","source_book":"元曲","prev":{"text":"幺·画屏咫尺巫山近，渍春衫都是啼痕。锦帐愁，香奁恨，最伤情处，酒","link":"/blogs/元曲·张可久/幺·画屏咫尺巫山近渍春衫都是啼痕锦帐愁香奁恨最伤情处酒.html"},"next":{"text":"双调·拨不断第一楼小集","link":"/blogs/元曲·张可久/双调·拨不断第一楼小集.html"}},"headers":[],"relativePath":"blogs/元曲·张可久/南吕·金字经偕叶云中山行.md","filePath":"blogs/元曲·张可久/南吕·金字经偕叶云中山行.md"}'),o={name:"blogs/元曲·张可久/南吕·金字经偕叶云中山行.md"};function l(n,a,c,m,z,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="南吕·金字经偕叶云中山行" tabindex="-1">南吕·金字经偕叶云中山行 <a class="header-anchor" href="#南吕·金字经偕叶云中山行" aria-label="Permalink to &quot;南吕·金字经偕叶云中山行&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">万里封侯贵，一场春梦中，破帽青鞋策短筇。</p><p class="poem-stanza">逢，南山采药翁。</p><p class="poem-stanza">桃花洞，白云千万重。</p><p class="poem-stanza">访吾丘道士细草眠白兔，小花啼翠禽，且听松风坐绿阴。</p><p class="poem-stanza">寻，洞天深又深。</p><p class="poem-stanza">游仙枕，顿消名利心。</p><p class="poem-stanza">青霞洞赵肃斋索赋酒后诗情放，水边归路差，何处青霞仙子家？沙，翠苔横古槎。</p><p class="poem-stanza">竹阴下，小鱼争柳花。</p><p class="poem-stanza">寿彦远卢使君胜境藏仙洞，浩歌来醉乡，菡萏花开十里塘。</p><p class="poem-stanza">香，户家白玉堂。</p><p class="poem-stanza">仙人仗，凤头萱草黄。</p><p class="poem-stanza">湖上寒食火冷尝仙饭，酒香撒鬼钱，细雨家家杨柳烟。</p><p class="poem-stanza">园，断桥西堍边。</p><p class="poem-stanza">秋千倦，玉人争画船。</p><p class="poem-stanza">环绿亭上水冷溪鱼贵，酒香霜蟹肥，环绿亭深掩翠微。</p><p class="poem-stanza">梅，落花浮玉杯。</p><p class="poem-stanza">山翁醉，笑随明月归。</p><p class="poem-stanza">开玄道院翠崦仙云暗，素琴冰涧长，画永人闲白玉堂。</p><p class="poem-stanza">尝，煮茶春水香。</p><p class="poem-stanza">玄泉上，鹤飞松露凉。</p><p class="poem-stanza">佛会万寿月面拂，十方云会僧。</p><p class="poem-stanza">宝殿香风秋树鸣。</p><p class="poem-stanza">青，莲花池上生。</p><p class="poem-stanza">灵上顶，半空玉磬声。</p><p class="poem-stanza">王国用胡琴雨漱窗前竹，涧流冰上泉，一线清风动二弦。</p><p class="poem-stanza">联，小山秋水篇。</p><p class="poem-stanza">昭君怨，塞云黄暮天。</p><p class="poem-stanza">题扇玉手银筝柱，翠涛金屈卮，正是鱼肥蟹健时。</p><p class="poem-stanza">诗，醉题秋扇儿。</p><p class="poem-stanza">黄华字，乱风摇柳丝。</p><p class="poem-stanza">次韵出岫白云笑，入山明月愁，两字功名四十秋。</p><p class="poem-stanza">羞，死封不义侯。</p><p class="poem-stanza">村学究，且读书青海头。</p><p class="poem-stanza">情云雨山头暗，女牛天上期，宝鼎香寒玉漏迟。</p><p class="poem-stanza">推，角门花影移。</p><p class="poem-stanza">鸳鸯会，莫教明月知。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
